import itertools
import math

def is_square(k):
    if k < 1:
        return False
    sqrt_k = int(math.sqrt(k))
    return sqrt_k * sqrt_k == k

def is_cool(n):
    numbers = list(range(1, n + 1))

    # Check all permutations
    for perm in itertools.permutations(numbers):
        partial_sum = 0
        is_valid = True
        for i in range(n):
            partial_sum += perm[i]
            if is_square(partial_sum):
                is_valid = False
                break

        if is_valid:
            return True
    return False

