def is_square(k):
    if k <= 0:
        return False
    sqrt_k = int(math.sqrt(k))
    return sqrt_k * sqrt_k == k

# Using a recursive backtracking function
def check_cool(n):
    # memoization/caching could be complex here due to state, 
    # standard backtracking is fine for N <= 15

    # used is a boolean array tracking used numbers 1 to n
    used = [False] * (n + 1) 

    def backtrack(current_sum, length):
        if length == n:
            # Found a valid permutation
            return True

        for next_num in range(1, n + 1):
            if not used[next_num]:
                new_sum = current_sum + next_num

                if not is_square(new_sum):
                    used[next_num] = True
                    if backtrack(new_sum, length + 1):
                        return True
                    # Backtrack
                    used[next_num] = False

        return False

    # Start the search
    return backtrack(0, 0)

# Check for n from 1 to 15
