import math

def is_square(n):
    if n < 0:
        return False
    root = int(math.sqrt(n))
    return root * root == n

def find_non_cool_up_to(N):
    non_cool = []
    for n in range(1, N + 1):
        S_n = n * (n + 1) // 2
        if is_square(S_n):
            non_cool.append(n)
    return non_cool

non_cool_100 = find_non_cool_up_to(100)
print(f"Non-cool integers up to 100: {non_cool_100}")
print(f"Count of non-cool integers up to 100: {len(non_cool_100)}")
